insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NL:accountant','2026-08-12',null,18.01,35580,20,0,0,0,8,6,0,3,2,39,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2411 Accountants; Dutch protected accountant title scope.','shortage_note','UWV lists accountants and controllers among higher-education occupations with strong current opportunities and identifies (AA and assistant) accountants among structurally promising financial occupations; 20/20.','visa_basis','There is no accountant-specific Dutch immigration fast track. Highly Skilled Migrant/GVVA access remains employer-, sponsor-, salary- and permit-dependent; 3/10.','salary_method','Studiekeuze123 Accountancy hbo bachelor estimated graduate starting salary EUR 2,965/month, annualised to EUR 35,580; transparent early-career proxy, not an occupation median; 6/10.','entry_basis','Professional accountant title normally requires higher education plus additional professional education and practical experience; 8/15.','entry_burden_basis','The accountant title is legally protected and requires NBA register entry; 2/5.'),'2026-08-12'),
('NL:financial-analyst','2026-08-12',null,18.01,35580,15,0,0,0,8,6,0,3,5,37,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2413 Financial Analysts; generic finance-analysis scope excluding separately regulated personal-advice activities.','shortage_note','UWV reports strong opportunities for financial professionals and growing demand for financial experts as data analysis becomes more important; 15/20.','visa_basis','No occupation-specific migration fast track; HSM/GVVA rules remain employer- and route-dependent; 3/10.','salary_method','Studiekeuze123 Finance & Control estimated graduate starting salary EUR 2,965/month, annualised to EUR 35,580; 6/10.','entry_basis','Bachelor-level finance/economics/quantitative business routes are common; 8/15.','entry_burden_basis','No universal statutory financial-analyst register; 5/5.'),'2026-08-12'),
('NL:business-analyst','2026-08-12',null,18.17,34956,15,0,0,0,8,4,0,3,5,35,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2421 Management and Organisation Analysts, constrained to business-analysis and organisation-improvement work.','shortage_note','UWV lists business consultants and bedrijfskundigen among structurally promising occupations; 15/20.','visa_basis','No Business Analyst-specific Dutch migration fast track; 3/10.','salary_method','Studiekeuze123 Bedrijfskunde estimated graduate starting salary EUR 2,913/month, annualised to EUR 34,956; 4/10.','entry_basis','Bachelor-level Bedrijfskunde/Business Administration routes provide structured entry; 8/15.','entry_burden_basis','No universal statutory business-analyst register; 5/5.'),'2026-08-12'),
('NL:supply-chain-analyst','2026-08-12',null,18.51,37536,15,0,0,0,8,6,0,3,5,37,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','Modern Supply Chain Analyst retained as NL career scope because procurement, planning, inventory and logistics analysis span multiple legacy ISCO-08 groups.','shortage_note','UWV identifies transport/logistics as a durable opportunity sector and production/transport planners as structurally promising; 15/20.','visa_basis','No supply-chain-specific immigration fast track; standard HSM/GVVA conditions apply as relevant; 3/10.','salary_method','Studiekeuze123 Logistics Management hbo bachelor estimated graduate starting salary EUR 3,128/month, annualised to EUR 37,536; 6/10.','entry_basis','Bachelor-level Logistics Management/Logistics Engineering routes provide structured entry; 8/15.','entry_burden_basis','No universal statutory supply-chain analyst register; 5/5.'),'2026-08-12'),
('NL:human-resources-specialist','2026-08-12',null,18.19,35004,5,0,0,0,8,6,0,3,5,27,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2423 Personnel and Careers Professionals; HR specialist scope.','shortage_note','Current reviewed UWV evidence does not directly establish generic HR specialists as a severe shortage occupation; limited 5/20 reflects broader organisation/strategy demand only.','visa_basis','No HR-specific Dutch migration fast track; 3/10.','salary_method','Studiekeuze123 Human Resource Management estimated graduate starting salary EUR 2,917/month, annualised to EUR 35,004; 6/10.','entry_basis','Bachelor-level HRM provides a direct professional route; 8/15.','entry_burden_basis','No universal statutory HR register; 5/5.'),'2026-08-12'),
('NL:marketing-specialist','2026-08-12',null,17.46,33600,0,0,0,0,8,4,0,3,5,20,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2431 Advertising and Marketing Professionals; marketing-specialist scope.','shortage_note','UWV notes demand for digital-marketing skills but the reviewed current evidence does not support an occupation-wide generic marketing shortage; 0/20.','visa_basis','No marketing-specific Dutch migration fast track; 3/10.','salary_method','Studiekeuze123 Commerciele Economie estimated graduate starting salary EUR 2,800/month, annualised to EUR 33,600; 4/10.','entry_basis','Bachelor-level commercial-economics/marketing routes provide structured entry; 8/15.','entry_burden_basis','No universal statutory marketing register; 5/5.'),'2026-08-12'),
('NL:auditor','2026-08-12',null,18.01,35580,15,0,0,0,5,6,0,3,1,30,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','ISCO-08 2411 Accountants, constrained to external/statutory financial-audit scope.','shortage_note','Audit shares the strong UWV labour-market signal for accountants, but the score is kept below the general Accountant profile because the evidence is profession-wide rather than external-audit-specific; 15/20.','visa_basis','No auditor-specific Dutch immigration fast track; 3/10.','salary_method','Studiekeuze123 Accountancy hbo bachelor estimated graduate starting salary EUR 2,965/month, annualised to EUR 35,580; used as an early-career accountancy proxy; 6/10.','entry_basis','Statutory audit responsibility requires progression beyond the bachelor through professional education and supervised practice; 5/15.','entry_burden_basis','Statutory external audit requires protected accountant status plus AFM/NBA registration conditions for the responsible external accountant; 1/5.'),'2026-08-12'),
('NL:project-manager','2026-08-12',null,18.17,34956,5,0,0,0,8,4,0,3,5,25,'career-opportunity-nl-v1','provisional',jsonb_build_object('classification_scope','Cross-sector Project Manager retained as NL career scope rather than forced into one legacy ISCO-08 unit group.','shortage_note','UWV reports sector-specific project-manager demand and added event project managers in 2026, but this is insufficient for a generic occupation-wide shortage claim; limited 5/20.','visa_basis','No project-manager-specific Dutch migration fast track; 3/10.','salary_method','Studiekeuze123 Bedrijfskunde estimated graduate starting salary EUR 2,913/month, annualised to EUR 34,956; broad early-career proxy; 4/10.','entry_basis','Bachelor-level business and sector-specific pathways provide structured entry, with management responsibility commonly requiring experience; 8/15.','entry_burden_basis','No universal statutory project-manager register; 5/5.'),'2026-08-12')
